ALTER TABLE "collection_batches" ADD CONSTRAINT "collection_batches_submission_consistent" CHECK (("collection_batches"."status" IN ('OPEN', 'IN_PROGRESS') AND "collection_batches"."submitted_at" IS NULL) OR ("collection_batches"."status" IN ('SUBMITTED', 'REMITTED', 'RECONCILED', 'CLOSED') AND "collection_batches"."submitted_at" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "collection_batches" ADD CONSTRAINT "collection_batches_reconciliation_consistent" CHECK (("collection_batches"."status" IN ('OPEN', 'IN_PROGRESS', 'SUBMITTED', 'REMITTED') AND "collection_batches"."reconciled_at" IS NULL AND "collection_batches"."reconciled_by_user_id" IS NULL AND "collection_batches"."reconciliation_notes" IS NULL) OR ("collection_batches"."status" IN ('RECONCILED', 'CLOSED') AND "collection_batches"."reconciled_at" IS NOT NULL AND "collection_batches"."reconciled_by_user_id" IS NOT NULL AND "collection_batches"."reconciliation_notes" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "collection_batches" ADD CONSTRAINT "collection_batches_closure_consistent" CHECK (("collection_batches"."status" <> 'CLOSED' AND "collection_batches"."closed_at" IS NULL AND "collection_batches"."closed_by_user_id" IS NULL AND "collection_batches"."close_notes" IS NULL) OR ("collection_batches"."status" = 'CLOSED' AND "collection_batches"."closed_at" IS NOT NULL AND "collection_batches"."closed_by_user_id" IS NOT NULL));--> statement-breakpoint
